// Sound board audio: chip streams as MAME 0.289 produces them, mixed for the host.
//
// MAME updates a stream to the current time before every chip access
// (sound_stream::update: samples 0..floor(t * rate) use the old state). The
// YM2151 stream (ymfm, clock / 64 = 55,930 Hz) is therefore generated by the
// board at each YM access; the MC1408 DAC and the HC55516 are piecewise-constant
// streams (1,536,000 Hz and 192,000 Hz in MAME) whose value changes take effect
// from sample floor(t * rate) + 1. Route gains: YM 0.10 (both outputs summed),
// DAC 0.25, CVSD 0.60 (williams_cvsd_sound_device::device_add_mconfig).
#pragma once

#include "stv/snd/ops.hpp"

#include <deque>
#include <vector>

namespace stv::snd {

constexpr uint32_t kYmRate = 3579545 / 64;       // ymfm opm sample_rate(clock)
constexpr uint32_t kDacRate = 48000 * 32;        // dac_device_base stream
constexpr uint32_t kCvsdRate = 48000 * 4;        // cvsd_device_base stream

// Stream sample index of a time: now.seconds * rate + attoseconds * rate / 1e18 (floor).
uint64_t sample_index(const Atto& t, uint32_t rate);

// HC55516 decoder, MAME hc55516_device (digital model), bit for bit.
struct Hc55516 {
    bool last_clock{};
    bool buffered_bit{};
    uint32_t shiftreg{};
    int32_t sylfilter{0x3f};
    int32_t intfilter{};
    int32_t next_sample{};
    void clock_w(bool state);      // cvsd_device_base::clock_w
    void digit_w(bool bit) { buffered_bit = bit; }
private:
    void process_bit(bool bit, bool clock_state);
};

class Mixer {
public:
    explicit Mixer(uint32_t out_rate = 48000);

    // producer side (sound board)
    void ym_sample(int32_t l, int32_t r);            // next YM stream sample
    void dac(const Atto& t, uint8_t code);
    void cvsd(const Atto& t, int32_t sample16);

    // Render every output sample that lies completely before `known` (all chip
    // changes up to that time have been delivered). Appends mono floats in -1..1.
    void render_until(const Atto& known, std::vector<float>& out);

    uint64_t ym_generated() const { return ym_base_ + ym_.size(); }
    // Exact mixer position for an online join (pending chip samples and levels).
    void save_state(std::vector<uint8_t>& out) const;
    bool load_state(const uint8_t*& p, const uint8_t* end);
    uint32_t out_rate() const { return out_rate_; }

private:
    struct Step { uint64_t index; float value; };   // value from stream sample `index` onwards
    float level_over(std::deque<Step>& steps, float& current, uint32_t rate, double t0, double t1);

    uint32_t out_rate_;
    uint64_t out_index_{};               // next output sample
    std::deque<float> ym_;               // YM stream samples from ym_base_
    uint64_t ym_base_{};
    std::deque<Step> dac_, cvsd_;
    float dac_level_{-1.0f};             // code 0 until the PIA drives port A
    float cvsd_level_{};
};

}  // namespace stv::snd
